"""Write the requested numbered score record using verified saved results only."""
import json,hashlib
from pathlib import Path
HERE=Path(__file__).resolve().parent
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
r=read(HERE/'results.json');v=read(HERE/'verification.json');q=read(HERE/'quality.json');inv=read(HERE/'inventory.json');ts=read(HERE/'timestamps.json')
assert v['passed'] and hashlib.sha256((HERE/'results.json').read_bytes()).hexdigest()==v['results_sha256']
g=r['group'];lines=['# Test01 영상 번호별 고정 GDI 모델 점수','', '2026-11-01. 기존 실험과 동일한 CNN·STT 결합 모델을 재학습 없이 적용하고 검산했다. 사용자 분류에 따른 정상 영상은 1·2·3·6·8·9번, 이상 움직임을 흉내 낸 영상은 4·5·7·10·11·12·13번이다. 요청에 따라 같은 사람끼리 짝맞춤하지 않고 영상별로 정리했다.','', '| 영상 번호 | 사용자 분류 | GDI 예측 평균 | 왼쪽 | 오른쪽 | 유효 구간 수 |','|---|---|---:|---:|---:|---:|']
for row in r['records']:
    condition='정상' if row['condition']=='normal' else '비정상 모사'
    if row['score'] is None:lines.append('| %d | %s | 산출 불가 | — | — | 0 |'%(row['number'],condition))
    else:lines.append('| %d | %s | **%.2f** | %.2f | %.2f | %d |'%(row['number'],condition,row['score'],row['left'],row['right'],row['valid_windows']))
lines += ['', '점수는 같은 영상의 구간·좌우·5개 분할 모델 예측을 평균한 값이다. 좌우 점수 차이가 실제 신체 비대칭의 정확한 측정값임을 보증하지 않는다. 구간 수나 모델 수를 사람 수로 세지 않는다.','', '## 정상·비정상 영상의 비교','', '- 정상 %d개 영상 평균: **%.2f점**, 영상별 범위 %.2f~%.2f점.'%(g['normal_n'],g['normal_mean'],*g['normal_range']),'- 비정상 모사 %d개 영상 평균: **%.2f점**, 영상별 범위 %.2f~%.2f점.'%(g['abnormal_n'],g['abnormal_mean'],*g['abnormal_range']),'- 영상마다 같은 비중을 준 정상-비정상 평균 차이: **%+.2f점**.'%g['normal_minus_abnormal']]
over=g['abnormal_above_lowest_normal_numbers']
lines += ['- 정상 영상 중 가장 낮은 점수 이상을 받은 비정상 모사 영상: **'+('·'.join(str(n)+'번' for n in over) if over else '없음')+'**.']
lines += ['', '**이번 13개 영상에서는 정상·비정상의 영상 평균 점수 범위가 겹치지 않았다.** 가장 낮은 정상과 가장 높은 비정상의 차이는 **%.2f점**이다. 이는 이번 촬영 묶음에서 뚜렷한 분리 신호를 확인한 결과다. 구간·분할 모델에 따라 점수가 달라질 수 있으며, 분할 모델 간 범위는 반복 촬영 오차나 신뢰구간이 아니다.'%g['minimum_between_group_gap']]
lines += ['', '이는 영상 단위 기술통계다. 사용자 분류와 점수 순서를 비교한 것이며 실제 GDI 정답에 대한 오차나 정상·비정상 판별 정확도는 아니다. 이상 움직임 정도의 수치 정답도 없어 번호 간 점수 순서를 실제 중증도 순서로 해석하지 않는다.','', '![영상 번호별 점수](video-scores.png)','', '## 유지한 처리 조건','', '- OpenPose BODY25의 기존 가중치와 공식 CPU 후처리, 기존 전체 기록 보간·평활화·좌우12특징을 그대로 사용했다. 한 사람만 검출된 프레임을 쓰고 다중 검출은 결측으로 남겼다. 신뢰도 1 초과는 앞서 승인한 별도 어댑터대로 원값을 보존했다.','- 원본 프레임 순서를 유지했다. 시간 재표본화·좌우 교환·영상 반전·점수 자르기·재학습·새 보정은 하지 않았다.','- 124프레임 창을 시작0,31,…,372에서 고르는 기존 방식이다. 필수 좌표 결측25% 제한을 유지했고, 길이가 부족한 창은 제외했다. 영상별 점수는 앞 최대496프레임을 덮는 이 창들의 평균이며, 긴 영상의 후반까지 모든 보행을 점수 평균에 넣은 것은 아니다.','- 이전 실험의 추가 수동 직선구간 점수와 혼동하지 않는다. 이번 표에는 기존 자동 구간 방식의 점수를 기록했다.','- 이전과 같은 54개 체크포인트(CNN24·STT25·좌우 결합STT5), 학습자료 한정 보정계수, 분할별 결합 비중을 그대로 재사용했다. 정상·비정상 라벨은 예측이 고정된 뒤 보고서 집계에만 사용했다.','', '## 입력 검사와 확인 범위','', '- 원영상 %d개, 총 %d프레임을 처리했다. 모두 1080×1920·평균30 FPS이며 길이는 %.2f~%.2f초다.'%(len(inv),sum(a['frames'] for a in inv),min(a['seconds'] for a in inv),max(a['seconds'] for a in inv))]
lines += ['- 실제 프레임 간격이 불규칙한 영상: '+', '.join('%d번(%d곳)'%(t['number'],len(t['unusual_intervals'])) for t in ts if t['unusual_intervals'])+'. 원본 간격을 바꾸지 않았으며 [시각 기록](timestamps.json)에 남겼다.']
lines += ['- 다중 검출로 결측 처리한 프레임: '+(', '.join('%d번 %d프레임'%(a['number'],a['ambiguous_frames']) for a in q if a.get('ambiguous_frames',0)) or '없음')+'.']
lines += ['- 점수 전 영상별 대표12프레임의 관절 겹침 그림을 검토했다. 전신 보행이 보이지만 회전·정지·비스듬한 시점·옷에 의한 가림이 섞인다. 대표 검토는 모든 프레임의 관절 정확도나 해부학적 좌우를 보증하지 않는다.','- 유효 창 수·시작·결측률·제외 사유는 [quality.json](quality.json)과 [windows.json](windows.json)에 있다. 산출 불가 영상도 결과에서 지우지 않는다.','', '## 검산과 저장','', '[verification.json](verification.json)은 다음을 확인했다.','', '- 원영상13개 불변, 열지도 %d청크와 관절JSON %d개의 SHA256 일치.'%(v['heatmap_chunks_sha256_verified'],v['body25_json_sha256_verified']),'- 입력 %d구간을 원좌표에서 재계산한 특징 차이 %.8f.'%(v['feature_windows'],v['feature_reconstruction_max']),'- 이전 실험의 전체 저장 예측 재현 최대 차이 %.8f점(기존 허용치0.0001점).'%v['previous_full_prediction_replay_max'],'- 동일 체크포인트54개 확인, 독립 결합식 재계산 최대 차이 %.3g, 영상 평균 재계산 최대 차이 %.3g점.'%(v['ensemble_rebuild_max'],v['summary_recalculation_max']),'', '실행은 [run_pose.py](run_pose.py)로 이전의 추론·후처리 코드를 그대로 불러왔고, [predict_videos.py](predict_videos.py)에서 이전 예측 함수를 재사용했다. [prepare_inputs.py](prepare_inputs.py)는 기존 전처리에 번호별 입력과 검토 그림을 연결한다. 새 패키지는 설치하지 않았다.','', '번호별 원수치는 [CSV](video-scores.csv)와 [results.json](results.json)에 있다. 코드·그림·요약·검산은 이 C 폴더, 열지도·관절JSON·큰 배열은 `D:/gait-research-data/D_P/self-video-test01-20261101`에 저장했다. 학교 서버의 별도 폴더는 `/abr/RESEARCH_USER/self-video-test01-20261101`이다. 다른 학습·예약·기존 실험은 변경하지 않았다.']
(HERE/'README.md').write_text('\n'.join(lines)+'\n',encoding='utf8');print('REPORT_WRITTEN')
